/* ──────────────────────────────────────────────────────────────────────────────
   PREA Icon registry — icons.ts
   Every icon on the Figma "Icons" page (PREA Space Design library, node 13-2218),
   exported as SVG from Figma so the glyphs are pixel-identical to the design.

   kind:
     stroke → monochrome outline (Lucide / Untitled UI style). Root <svg> sets
              stroke=currentColor, stroke-width, round caps/joins.
     fill   → monochrome filled glyph. Root <svg> sets fill=currentColor.
     color  → multi-colour asset (brand logos, status badges). Colours are baked in.

   Look-ups are case-insensitive and accept the name with or without the "li:"
   prefix (see Icon.tsx → resolveIcon).
   ────────────────────────────────────────────────────────────────────────────── */

export type IconKind = 'stroke' | 'fill' | 'color';

export interface IconDef {
  /** SVG viewBox, e.g. "0 0 24 24" */
  viewBox: string;
  kind: IconKind;
  /** Inner SVG markup (paths, rects, defs…) */
  body: string;
}

